import{c as l,Q as t,j as i,m as o}from"./chunks/framework.BPKcPtvA.js";const r="/images/class-IHhicsbtsBwqzyj.jpg",g=JSON.parse('{"title":"牧师攻略 - 技能加点/转职/练级","description":"RO3 牧师 1-99 级技能加点、转职任务、练级路线、组队指南","frontmatter":{"title":"牧师攻略 - 技能加点/转职/练级","description":"RO3 牧师 1-99 级技能加点、转职任务、练级路线、组队指南"},"headers":[],"relativePath":"jobs/aco.md","filePath":"jobs/aco.md","lastUpdated":1780230058000}'),e={name:"jobs/aco.md"};function s(n,a,h,c,d,p){return t(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="牧师-推荐组队玩家-零氪" tabindex="-1">牧师（推荐组队玩家/零氪） <a class="header-anchor" href="#牧师-推荐组队玩家-零氪" aria-label="Permalink to &quot;牧师（推荐组队玩家/零氪）&quot;">​</a></h1><p><img src="'+r+'" alt="RO3 牧师职业立绘"></p><p>牧师是组队必备职业，不需要输出装备，零氪也能玩得很舒服，组队需求极高。玩牧师的玩家永远不愁找不到队伍。</p><h2 id="技能加点" tabindex="-1">技能加点 <a class="header-anchor" href="#技能加点" aria-label="Permalink to &quot;技能加点&quot;">​</a></h2><p><strong>1-10 级</strong>：点满「治愈术」（核心治疗技能），「天使之护」点 5 级（加防御）</p><p><strong>11-30 级</strong>：点满「加速术」（组队神技，加移速和攻速），「天使之护」点满</p><p><strong>31-60 级</strong>：点满「复活术」（救死扶伤，组队必点），「神圣之光」点满（唯一输出技能，打不死系用）</p><p><strong>61-99 级</strong>：点满「治愈之光」（群疗），「天使之障壁」点满（加全队魔防），剩余点「冥想」（回蓝速度）</p><h2 id="转职任务流程-20级转职" tabindex="-1">转职任务流程（20级转职） <a class="header-anchor" href="#转职任务流程-20级转职" aria-label="Permalink to &quot;转职任务流程（20级转职）&quot;">​</a></h2><ol><li>普隆德拉教堂找「大主教」（坐标 140,90），接取任务</li><li>向教会捐赠 10 万z（可交易，提前准备）</li><li>对 NPC 使用 100 次「治愈术」（脱装备降低 SP 消耗反复使用即可）</li><li>完成任务，获得牧师资格</li></ol><h2 id="各等级段练级点" tabindex="-1">各等级段练级点 <a class="header-anchor" href="#各等级段练级点" aria-label="Permalink to &quot;各等级段练级点&quot;">​</a></h2><ul><li><strong>1-20 级</strong>：跟着队伍混，负责加血和加 buff（治愈术+加速术）</li><li><strong>21-60 级</strong>：组剑士/法师队伍，自己负责治疗和 buff，经验分成</li><li><strong>61-99 级</strong>：高级副本治疗位，热门组队职业，永远缺牧师</li></ul><h2 id="配装思路" tabindex="-1">配装思路 <a class="header-anchor" href="#配装思路" aria-label="Permalink to &quot;配装思路&quot;">​</a></h2><ul><li><strong>武器</strong>：高 INT 法杖（提升治疗量）</li><li><strong>防具</strong>：高 DEF 铠甲（生存优先）</li><li><strong>饰品</strong>：回蓝属性优先</li></ul><h2 id="组队技巧" tabindex="-1">组队技巧 <a class="header-anchor" href="#组队技巧" aria-label="Permalink to &quot;组队技巧&quot;">​</a></h2><ul><li>开怪前先给全队上「加速术」和「天使之护」</li><li>坦克掉血到 70% 再治疗，避免过量治疗浪费 SP</li><li>复活术优先给治疗/输出，坦克最后拉</li><li>BOSS 战注意走位躲技能，你活着队伍才安全</li></ul><h2 id="省钱攻略" tabindex="-1">省钱攻略 <a class="header-anchor" href="#省钱攻略" aria-label="Permalink to &quot;省钱攻略&quot;">​</a></h2><p>零氪牧师玩法：</p><ul><li>不需要高强武器（治疗量跟武器无关）</li><li>不需要极品防具（有队友帮你拉怪）</li><li>学会后还可以带小号收费，赚外快</li></ul>',19)])])}const _=l(e,[["render",s]]);export{g as __pageData,_ as default};
